<style>
/* ── Design Tokens ── */
:root {
  --color-primary: oklch(42% 0.13 165);
  --color-primary-hex: #2D6A4F;
  --color-primary-light: oklch(55% 0.10 165);
  --color-primary-lighter: oklch(88% 0.04 165);
  --color-accent: oklch(76% 0.15 60);
  --color-accent-hex: #F4A261;
  --color-accent-dark: oklch(65% 0.16 50);
  --color-cream: oklch(97% 0.04 100);
  --color-cream-hex: #FEFAE0;
  --color-white: oklch(100% 0 0);
  --color-text: oklch(22% 0.02 165);
  --color-text-light: oklch(45% 0.02 165);
  --color-text-muted: oklch(65% 0.02 165);

  --font-heading: 'Nunito', 'Segoe UI', system-ui, sans-serif;
  --font-body: 'Inter', system-ui, -apple-system, sans-serif;

  --radius-sm: 8px;
  --radius-md: 12px;
  --radius-lg: 16px;
  --radius-xl: 24px;
  --radius-full: 9999px;

  --shadow-sm: 0 1px 3px oklch(0% 0 0 / 0.08);
  --shadow-md: 0 4px 16px oklch(0% 0 0 / 0.10);
  --shadow-lg: 0 8px 32px oklch(0% 0 0 / 0.12);
  --shadow-xl: 0 16px 48px oklch(0% 0 0 / 0.14);

  --space-1: 4px;
  --space-2: 8px;
  --space-3: 16px;
  --space-4: 24px;
  --space-5: 32px;
  --space-6: 48px;
  --space-7: 64px;
  --space-8: 96px;

  --max-width: 1200px;
  --header-height: 72px;
}

/* ── Reset ── */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }
html { scroll-behavior: smooth; scroll-padding-top: var(--header-height); }
body {
  font-family: var(--font-body);
  font-size: 16px;
  line-height: 1.6;
  color: var(--color-text);
  background: var(--color-cream);
  -webkit-font-smoothing: antialiased;
}
img { max-width: 100%; height: auto; display: block; }
a { color: inherit; text-decoration: none; }
button { cursor: pointer; font: inherit; border: none; background: none; }
input { font: inherit; }
ul, ol { list-style: none; }

/* ── Focus ── */
:focus-visible { outline: 2px solid var(--color-primary); outline-offset: 2px; }

/* ── Utility ── */
.container { max-width: var(--max-width); margin: 0 auto; padding: 0 var(--space-4); }
.sr-only { position: absolute; width: 1px; height: 1px; padding: 0; margin: -1px; overflow: hidden; clip: rect(0, 0, 0, 0); white-space: nowrap; border: 0; }

/* ── Header ── */
.site-header {
  position: sticky; top: 0; z-index: 100;
  background: oklch(100% 0 0 / 0.92);
  backdrop-filter: blur(12px);
  -webkit-backdrop-filter: blur(12px);
  border-bottom: 1px solid oklch(0% 0 0 / 0.06);
  height: var(--header-height);
}
.site-header .container { display: flex; align-items: center; justify-content: space-between; height: 100%; }
.header-logo {
  display: flex; align-items: center; gap: var(--space-2);
  font-family: var(--font-heading); font-weight: 800; font-size: 1.35rem;
  color: var(--color-primary);
}
.header-logo svg { width: 32px; height: 32px; flex-shrink: 0; }
.header-nav { display: flex; align-items: center; gap: var(--space-5); }
.header-nav a {
  font-family: var(--font-heading); font-weight: 600; font-size: 0.95rem;
  color: var(--color-text); padding: var(--space-1) 0;
  border-bottom: 2px solid transparent;
  transition: border-color 0.2s, color 0.2s;
}
.header-nav a:hover, .header-nav a:focus-visible { color: var(--color-primary); border-bottom-color: var(--color-primary); }
.header-cta {
  font-family: var(--font-heading); font-weight: 700; font-size: 0.9rem;
  background: var(--color-primary); color: var(--color-white);
  padding: var(--space-2) var(--space-4); border-radius: var(--radius-full);
  transition: background 0.2s, transform 0.15s;
}
.header-cta:hover { background: var(--color-primary-light); transform: translateY(-1px); }
.menu-toggle { display: none; flex-direction: column; gap: 5px; padding: var(--space-2); }
.menu-toggle span { width: 24px; height: 2.5px; background: var(--color-text); border-radius: 2px; transition: transform 0.3s, opacity 0.3s; }

/* ── Hero ── */
.hero {
  padding: var(--space-8) 0 var(--space-7);
  background: linear-gradient(165deg, oklch(93% 0.04 110) 0%, var(--color-cream) 50%, oklch(95% 0.05 80) 100%);
  position: relative; overflow: hidden;
}
.hero::before {
  content: ''; position: absolute; top: -60px; right: -80px;
  width: 320px; height: 320px; border-radius: 50%;
  background: oklch(76% 0.15 60 / 0.12);
}
.hero::after {
  content: ''; position: absolute; bottom: -40px; left: -60px;
  width: 200px; height: 200px; border-radius: 50%;
  background: oklch(42% 0.13 165 / 0.08);
}
.hero .container { position: relative; z-index: 1; text-align: center; }
.hero-icon { margin: 0 auto var(--space-4); width: 64px; height: 64px; }
.hero h1 {
  font-family: var(--font-heading); font-weight: 800; font-size: clamp(2.2rem, 5vw, 3.6rem);
  line-height: 1.15; color: var(--color-primary); margin-bottom: var(--space-3);
}
.hero p {
  font-size: clamp(1rem, 2vw, 1.2rem); color: var(--color-text-light);
  max-width: 620px; margin: 0 auto var(--space-5); line-height: 1.7;
}
.hero-actions { display: flex; flex-wrap: wrap; gap: var(--space-3); justify-content: center; }
.btn {
  display: inline-flex; align-items: center; gap: var(--space-2);
  font-family: var(--font-heading); font-weight: 700; font-size: 1rem;
  padding: 14px 28px; border-radius: var(--radius-full);
  transition: background 0.2s, transform 0.15s, box-shadow 0.2s;
}
.btn:hover { transform: translateY(-2px); }
.btn-primary { background: var(--color-primary); color: var(--color-white); box-shadow: var(--shadow-md); }
.btn-primary:hover { background: var(--color-primary-light); box-shadow: var(--shadow-lg); }
.btn-outline { background: var(--color-white); color: var(--color-primary); border: 2px solid var(--color-primary); }
.btn-outline:hover { background: var(--color-primary-lighter); }

/* ── Section Headers ── */
.section-header { text-align: center; margin-bottom: var(--space-6); }
.section-label {
  display: inline-block; font-family: var(--font-heading); font-weight: 700; font-size: 0.85rem;
  text-transform: uppercase; letter-spacing: 0.08em;
  color: var(--color-accent-dark); margin-bottom: var(--space-2);
}
.section-title {
  font-family: var(--font-heading); font-weight: 800; font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  color: var(--color-text); margin-bottom: var(--space-2);
}
.section-subtitle { color: var(--color-text-light); font-size: 1.05rem; max-width: 520px; margin: 0 auto; }

/* ── Sections ── */
section { padding: var(--space-7) 0; }
section:nth-child(even) { background: var(--color-white); }

/* ── Featured Products Carousel ── */
.carousel-wrapper { position: relative; overflow: hidden; }
.carousel-track {
  display: flex; gap: var(--space-4);
  overflow-x: auto; scroll-snap-type: x mandatory;
  scrollbar-width: none; -ms-overflow-style: none;
  padding: var(--space-2) 0 var(--space-4);
  scroll-behavior: smooth;
}
.carousel-track::-webkit-scrollbar { display: none; }
.carousel-btn {
  position: absolute; top: 50%; transform: translateY(-50%); z-index: 5;
  width: 44px; height: 44px; border-radius: 50%;
  background: var(--color-white); box-shadow: var(--shadow-md);
  display: flex; align-items: center; justify-content: center;
  transition: background 0.2s, box-shadow 0.2s, transform 0.15s;
}
.carousel-btn:hover { background: var(--color-primary-lighter); box-shadow: var(--shadow-lg); }
.carousel-btn:active { transform: translateY(-50%) scale(0.95); }
.carousel-btn--prev { left: -4px; }
.carousel-btn--next { right: -4px; }
.carousel-btn svg { width: 20px; height: 20px; color: var(--color-primary); }

.product-card {
  flex: 0 0 280px; scroll-snap-align: start;
  background: var(--color-white); border-radius: var(--radius-lg);
  overflow: hidden; box-shadow: var(--shadow-sm);
  transition: transform 0.25s, box-shadow 0.25s;
}
.product-card:hover { transform: translateY(-4px); box-shadow: var(--shadow-md); }
.product-card-img {
  height: 200px; background: oklch(90% 0.04 130);
  display: flex; align-items: center; justify-content: center;
  font-size: 3rem; position: relative; overflow: hidden;
}
.product-card-img img { width: 100%; height: 100%; object-fit: cover; }
.product-card-body { padding: var(--space-3); }
.product-card-body h3 { font-family: var(--font-heading); font-weight: 700; font-size: 1.05rem; margin-bottom: var(--space-1); color: var(--color-text); }
.product-card-body p { font-size: 0.88rem; color: var(--color-text-light); margin-bottom: var(--space-2); line-height: 1.5; }
.product-card-price {
  font-family: var(--font-heading); font-weight: 800; font-size: 1.2rem;
  color: var(--color-primary);
}

/* ── Seasonal Picks ── */
.seasonal-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(260px, 1fr));
  gap: var(--space-4);
}
.seasonal-card {
  background: var(--color-white); border-radius: var(--radius-lg);
  padding: var(--space-4); box-shadow: var(--shadow-sm);
  display: flex; gap: var(--space-3);
  border: 1px solid oklch(0% 0 0 / 0.05);
  transition: transform 0.2s, box-shadow 0.2s;
}
.seasonal-card:hover { transform: translateY(-2px); box-shadow: var(--shadow-md); }
.seasonal-card-icon {
  width: 56px; height: 56px; flex-shrink: 0; border-radius: var(--radius-md);
  background: oklch(88% 0.04 165); display: flex; align-items: center; justify-content: center;
  font-size: 1.6rem;
}
.seasonal-card-info h3 { font-family: var(--font-heading); font-weight: 700; font-size: 0.95rem; margin-bottom: 2px; }
.seasonal-card-info p { font-size: 0.82rem; color: var(--color-text-light); line-height: 1.5; }
.seasonal-card-price {
  font-family: var(--font-heading); font-weight: 800; font-size: 1rem;
  color: var(--color-accent-dark); margin-top: var(--space-1);
}

/* ── Categories ── */
.categories-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(200px, 1fr));
  gap: var(--space-4);
}
.category-card {
  position: relative; border-radius: var(--radius-lg); overflow: hidden;
  aspect-ratio: 1 / 1; box-shadow: var(--shadow-sm);
  cursor: pointer; transition: transform 0.3s cubic-bezier(0.34, 1.56, 0.64, 1), box-shadow 0.3s;
}
.category-card:hover { transform: scale(1.05); box-shadow: var(--shadow-lg); }
.category-card-bg {
  width: 100%; height: 100%;
  display: flex; align-items: center; justify-content: center;
  font-size: 3.5rem;
}
.category-card-overlay {
  position: absolute; inset: 0;
  background: linear-gradient(to top, oklch(0% 0 0 / 0.55) 0%, oklch(0% 0 0 / 0.05) 60%);
  display: flex; align-items: flex-end; padding: var(--space-3);
  opacity: 1; transition: opacity 0.3s;
}
.category-card:hover .category-card-overlay { opacity: 1; }
.category-card-overlay span {
  font-family: var(--font-heading); font-weight: 700; font-size: 1.1rem; color: white;
}
.category-card-desc {
  position: absolute; inset: 0; display: flex; flex-direction: column;
  align-items: center; justify-content: center;
  background: oklch(0% 0 0 / 0.35);
  opacity: 0; transition: opacity 0.3s; padding: var(--space-4); text-align: center;
}
.category-card:hover .category-card-desc { opacity: 1; }
.category-card-desc p { color: white; font-size: 0.88rem; line-height: 1.5; }

/* ── Brand Stats ── */
.stats-banner {
  background: linear-gradient(135deg, var(--color-primary) 0%, var(--color-primary-light) 100%);
  color: var(--color-white); padding: var(--space-7) 0; text-align: center;
}
.stats-grid {
  display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr));
  gap: var(--space-5); max-width: 900px; margin: 0 auto;
}
.stat-item { padding: var(--space-3); }
.stat-number {
  font-family: var(--font-heading); font-weight: 800; font-size: clamp(1.8rem, 3.5vw, 2.5rem);
  line-height: 1.1; margin-bottom: var(--space-1);
}
.stat-label { font-size: 0.9rem; opacity: 0.85; line-height: 1.5; }

/* ── Store Locator ── */
.locator-form {
  display: flex; gap: var(--space-2); max-width: 440px; margin: 0 auto var(--space-5);
}
.locator-form input {
  flex: 1; padding: 14px 20px; border: 2px solid oklch(0% 0 0 / 0.12);
  border-radius: var(--radius-full); font-size: 1rem; min-width: 0;
  transition: border-color 0.2s;
}
.locator-form input:focus { border-color: var(--color-primary); outline: none; }
.locator-form .btn { white-space: nowrap; padding: 14px 28px; }
.store-results { max-width: 800px; margin: 0 auto; display: none; }
.store-results.visible { display: block; }
.store-card {
  display: flex; align-items: flex-start; gap: var(--space-3);
  background: var(--color-white); border-radius: var(--radius-md);
  padding: var(--space-3) var(--space-4); box-shadow: var(--shadow-sm);
  margin-bottom: var(--space-2); border: 1px solid oklch(0% 0 0 / 0.05);
  transition: box-shadow 0.2s;
}
.store-card:hover { box-shadow: var(--shadow-md); }
.store-card-icon { width: 44px; height: 44px; flex-shrink: 0; color: var(--color-accent-hex); }
.store-card-info { flex: 1; min-width: 0; }
.store-card-info h4 { font-family: var(--font-heading); font-weight: 700; font-size: 1rem; }
.store-card-info p { font-size: 0.85rem; color: var(--color-text-light); }
.store-card-distance {
  text-align: right; flex-shrink: 0;
  font-family: var(--font-heading); font-weight: 700; font-size: 0.95rem;
  color: var(--color-primary);
}
.store-empty {
  text-align: center; padding: var(--space-5); color: var(--color-text-muted); display: none;
}
.store-empty.visible { display: block; }

/* ── Newsletter ── */
.newsletter-card {
  max-width: 520px; margin: 0 auto; text-align: center;
  background: var(--color-white); border-radius: var(--radius-xl);
  padding: var(--space-6); box-shadow: var(--shadow-md);
  border: 1px solid oklch(0% 0 0 / 0.05);
}
.newsletter-form {
  display: flex; gap: var(--space-2); margin-top: var(--space-4);
}
.newsletter-form input {
  flex: 1; padding: 14px 20px; border: 2px solid oklch(0% 0 0 / 0.12);
  border-radius: var(--radius-full); font-size: 1rem; min-width: 0;
  transition: border-color 0.2s;
}
.newsletter-form input:focus { border-color: var(--color-primary); outline: none; }
.newsletter-confirm {
  display: none; color: var(--color-primary); font-weight: 600;
  margin-top: var(--space-3); padding: var(--space-3);
  background: var(--color-primary-lighter); border-radius: var(--radius-md);
}
.newsletter-confirm.visible { display: block; }

/* ── Footer ── */
.site-footer {
  background: var(--color-primary); color: white; padding: var(--space-7) 0 var(--space-4);
}
.footer-grid { display: grid; grid-template-columns: repeat(auto-fit, minmax(180px, 1fr)); gap: var(--space-5); margin-bottom: var(--space-6); }
.footer-col h4 { font-family: var(--font-heading); font-weight: 700; font-size: 0.95rem; margin-bottom: var(--space-3); opacity: 0.9; }
.footer-col a { display: block; font-size: 0.88rem; opacity: 0.75; margin-bottom: var(--space-1); transition: opacity 0.2s; }
.footer-col a:hover { opacity: 1; }
.footer-bottom {
  border-top: 1px solid oklch(100% 0 0 / 0.15);
  padding-top: var(--space-4); text-align: center;
  font-size: 0.85rem; opacity: 0.7;
}

/* ── Responsive ── */
@media (max-width: 768px) {
  .header-nav { display: none; }
  .menu-toggle { display: flex; }
  .header-nav.open {
    display: flex; flex-direction: column; position: absolute;
    top: var(--header-height); left: 0; right: 0;
    background: var(--color-white); padding: var(--space-4);
    box-shadow: var(--shadow-lg); gap: var(--space-2);
  }
  .header-cta.desktop { display: none; }
  .hero { padding: var(--space-6) 0 var(--space-5); }
  section { padding: var(--space-5) 0; }
  .carousel-btn { display: none; }
  .product-card { flex: 0 0 240px; }
  .newsletter-form { flex-direction: column; }
  .locator-form { flex-direction: column; }
}

@media (min-width: 769px) {
  .menu-toggle { display: none; }
  .header-cta.mobile { display: none; }
}

@media (max-width: 480px) {
  .categories-grid { grid-template-columns: repeat(2, 1fr); }
  .seasonal-grid { grid-template-columns: 1fr; }
  .stats-grid { grid-template-columns: 1fr 1fr; }
}
</style>
</head>
